CREATE TABLE IF NOT EXISTS network_interfaces(id UUID PRIMARY KEY,device_id UUID NOT NULL REFERENCES devices(id) ON DELETE CASCADE,name VARCHAR(160) NOT NULL,description VARCHAR(300),status VARCHAR(30) DEFAULT 'UNKNOWN',speed_mbps VARCHAR(40),duplex VARCHAR(40),traffic_in_mbps DOUBLE PRECISION,traffic_out_mbps DOUBLE PRECISION,error_rate DOUBLE PRECISION,utilization_percent DOUBLE PRECISION,updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE INDEX IF NOT EXISTS idx_interfaces_device ON network_interfaces(device_id);
CREATE TABLE IF NOT EXISTS service_monitors(id UUID PRIMARY KEY,device_id UUID NOT NULL REFERENCES devices(id) ON DELETE CASCADE,name VARCHAR(160) NOT NULL,protocol VARCHAR(30) NOT NULL,port INTEGER,endpoint VARCHAR(300),status VARCHAR(30) DEFAULT 'UNKNOWN',response_time_ms BIGINT,last_checked_at TIMESTAMPTZ);CREATE INDEX IF NOT EXISTS idx_services_device ON service_monitors(device_id);